                  <button type="button" onClick={() => { const cols = ['modo', 'fecha_demo', 'documento_demo', 'tipo', 'contraparte_demo', 'total_bruto_crc', 'impuesto', 'estado_fiscal', 'soporte']; const rows = CONCILIACION_FISCAL_DEMO_R6.map(f => ['DEMO_NO_FISCAL', f.fecha, f.documento, f.tipo, f.cliente, f.total, 'NO_CALCULADO', f.estadoImpuesto, f.soporte]); const safe = (v: unknown) => { if (typeof v === 'number') return String(v); const s = String(v ?? ''); return `"${s.replace(/"/g, '""')}"`; }; const csv = `\uFEFF${[cols, ...rows].map(row => row.map(safe).join(',')).join('\r\n')}`; const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = 'DEMO-NO-FISCAL-preparacion-contador.csv'; a.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); toast.success('Archivo demo descargado; no es declaración ni comprobante fiscal.'); }} className="mt-3 rounded-md border border-amber-400 px-3 py-2 text-xs font-bold hover:bg-amber-100 dark:hover:bg-neutral-800">Descargar paquete fiscal ficticio para revisión</button>
